import {
  existsSync,
  mkdirSync,
  readFileSync,
  renameSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname } from "node:path";

/**
 * Standard auto-generated banner prepended to every emitted `.g.ts` file.
 * Format mirrors the .NET SourceGen-emitted banner so cross-language
 * grep / tooling lights up identically.
 */
export function buildHeader(specRelativePath: string): string {
  return [
    "// -----------------------------------------------------------------------",
    "// <auto-generated>",
    "//   Generated by tools/ts-codegen — see this script's source for details.",
    `//   Source spec: ${specRelativePath}`,
    "//   Manual edits will be lost on rebuild.",
    "// </auto-generated>",
    "// -----------------------------------------------------------------------",
    "",
  ].join("\n");
}

/**
 * Atomically write a generated source file. If the existing content is
 * byte-identical, returns `false` (no write happened) so the orchestrator
 * can report "no diff" cleanly.
 */
export function writeGeneratedFile(
  targetPath: string,
  content: string,
): boolean {
  if (existsSync(targetPath)) {
    const existing = readFileSync(targetPath, "utf8");
    if (existing === content) return false;
  }
  const dir = dirname(targetPath);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  const tmp = `${targetPath}.tmp`;
  writeFileSync(tmp, content, "utf8");
  renameSync(tmp, targetPath);
  return true;
}

/**
 * Returns true if `targetPath` exists AND its mtime is newer-or-equal
 * than every file in `sourcePaths`. Each per-topic emitter calls this
 * before doing work so unchanged builds skip the parse + emit cost.
 */
export function isOutputUpToDate(
  targetPath: string,
  sourcePaths: readonly string[],
): boolean {
  if (!existsSync(targetPath)) return false;
  const targetMtime = statSync(targetPath).mtimeMs;
  for (const src of sourcePaths) {
    if (!existsSync(src)) return false;
    if (statSync(src).mtimeMs > targetMtime) return false;
  }
  return true;
}
